/**
 * One command runs every detector across the corpus and computes every endpoint.
 *
 * Reproducible from a seed on a clean machine: the corpus is regenerated by
 * `outbreak-simulation.ts` from the grid's seeds rather than read from disk, so a run needs
 * nothing but this repository and produces the same numbers anywhere.
 *
 * ## The order of operations, which is not negotiable
 *
 * 1. Generate the **null** replicates and run every arm over them.
 * 2. Calibrate each arm to the target alerts per site-year on those nulls alone.
 * 3. Only then generate the seeded cells and run every arm over them at its calibrated
 *    threshold.
 *
 * Calibrating on data that contains the outbreaks would let each detector set its threshold
 * with knowledge of the thing it is being asked to find, and would make the false-alert rate a
 * function of the seeded signal. The nulls exist so that does not happen, and the sequence is
 * enforced by the code rather than left to whoever runs it.
 *
 * ## Arms, and why PACE needs no change here
 *
 * An arm is a detector plus a settings object plus a label. The ablation grid Phase 31 needs is
 * therefore several arms over the same detector with different components switched off, and
 * requires nothing from this file. `armsFor` builds the default set; a caller may pass its own.
 */

import {
  PACE_ID, SPACE_TIME_PERMUTATION_ID, getDetector, type DetectorContext, type DetectorSignal
} from '../detection/registry'
import { antibioticClasses } from './catalogue'
import {
  factorialDesign, simulate, type BackgroundRate, type FactorialCell, type OutbreakType,
  type SeededOutbreak
} from '../outbreak-simulation'
import { DEMO_SITES } from '../demo-population'
import { alerted, calibrate, siteYearsOf, type Calibration } from './calibration'
import {
  endpointsFromRows, outcomeOf, rowOf, type CellRow, type Endpoints
} from './endpoints'
import { evidenceOf, rankableDetectors } from './ranking'
import type { IsolateRecord } from '../../shared/types'

const DAY_MS = 86_400_000
const day = (value: string): number => Math.round(Date.parse(`${value}T00:00:00Z`) / DAY_MS)
const dayKey = (value: number): string => new Date(value * DAY_MS).toISOString().slice(0, 10)

export interface BenchmarkArm {
  id: string
  detectorId: string
  label: string
  settings: Record<string, unknown>
}

/**
 * Settings every arm shares, and the one that matters.
 *
 * `permutations` is 99, not the shipped 999. That would disable alerting in production —
 * Phase 32 measured the recurrence-interval ceiling at `permutations + 1` — and it is
 * harmless here for one reason: nothing in this harness reads a p-value or a recurrence
 * interval. Arms are ranked by their own evidence statistic and calibrated empirically, and
 * the scan family's statistic is the log-likelihood ratio, which is deterministic given the
 * data and unaffected by the replication count. See `ranking.ts`.
 */
export const BENCHMARK_SETTINGS: Readonly<Record<string, unknown>> = Object.freeze({
  permutations: 99,
  analysisType: 'prospective'
})

export function armsFor(detectorIds: readonly string[] = rankableDetectors()): BenchmarkArm[] {
  return detectorIds.map((detectorId) => ({
    id: detectorId,
    detectorId,
    label: getDetector(detectorId).descriptor.name,
    settings: { ...BENCHMARK_SETTINGS }
  }))
}

/**
 * The Phase 31 ablation grid: PACE, its components switched off one at a time, and the control.
 *
 * An ablation arm differs from the full detector in exactly one component, so a difference in
 * an endpoint is attributable to that component and to nothing else. The control arm is the
 * registered `space-time-permutation` detector rather than a PACE arm configured to imitate it,
 * because a control that shares an implementation with the thing it controls is not a control —
 * even though, as it happens, PACE with pooling off and one model *is* that scan, and a test
 * asserts it.
 *
 * **Component 3 is not measurable through the endpoints here, by construction.** The harness
 * calibrates every arm to a matched empirical alert rate on the null replicates, which replaces
 * whatever threshold a detector would have chosen for itself; that is the entire point of Phase
 * 33 and it is what makes the sensitivity figures comparable. So the `pace-no-calibration` arm
 * will report the same sensitivity as the full detector. What it does not report the same is
 * `nativeAlertsPerSiteYear` — the alerts the detector's *own* rule would have raised on the null
 * corpora — and that column is where component 3 is measured.
 */
export function paceAblationArms(): BenchmarkArm[] {
  const pace = (id: string, label: string, settings: Record<string, unknown>): BenchmarkArm => ({
    id, detectorId: PACE_ID, label, settings: { ...BENCHMARK_SETTINGS, ...settings }
  })
  return [
    pace('pace', 'PACE (all four components)', {}),
    pace('pace-no-aggregation', 'PACE minus phenotype aggregation', { aggregatePhenotypes: false }),
    pace('pace-case-only', 'PACE minus the proportion model', { models: 'case-only' }),
    pace('pace-proportion-only', 'PACE minus the case-only model', { models: 'proportion' }),
    pace('pace-no-calibration', 'PACE minus the empirical threshold', { calibrateThreshold: false }),
    pace('pace-no-rerank', 'PACE minus plausibility re-ranking', { rerankByPlausibility: false }),
    ...armsFor([SPACE_TIME_PERMUTATION_ID])
  ]
}

export interface BenchmarkOptions {
  arms?: readonly BenchmarkArm[]
  /** Grid controls, passed to `factorialDesign`. A reduced grid is what CI runs. */
  excessCases?: readonly number[]
  durationDays?: readonly number[]
  backgroundRates?: readonly BackgroundRate[]
  types?: readonly OutbreakType[]
  replicates?: number
  nullReplicates?: number
  baseSeed?: number
  /** Days of data per cell. */
  windowDays?: number
  /**
   * Sites per cell, taken from the head of `DEMO_SITES`.
   *
   * Left unset it is derived from the grid, because `factorialDesign` pins each outbreak type
   * to a particular site — the proportion shift is seeded at `DEMO-KOL-01`, the single-agent
   * cluster at `DEMO-MUM-01` — and a run that supplies fewer sites than the grid references
   * cannot generate its own corpus. Set it explicitly and the harness checks it is enough
   * rather than failing halfway through a long run.
   */
  sites?: number
  /** Target alerts per site-year. The plan's default is 1. */
  targetRate?: number
  /** Days between successive data cuts when measuring detection delay. 0 disables it. */
  delayStrideDays?: number
  /** Most cuts to evaluate per outbreak, bounding the cost of the delay measurement. */
  maxDelayCuts?: number
  /**
   * Which **seeded** cells this process evaluates, as `[index, count]` over the design.
   *
   * The null cells are always run in full regardless, because they are what the calibration is
   * computed from and a threshold set on a fraction of the null corpus is a different threshold.
   * Given that, and given that each arm calibrates on its own signals alone, a shard's endpoints
   * over its slice are exactly the endpoints that slice would have contributed to a single run —
   * so shards pool by concatenating their `cells` rows. Splitting the *design* instead (by type,
   * say) would be wrong: `factorialDesign` numbers its seeds sequentially, so dropping a type
   * shifts every null seed and the shards would calibrate against different null corpora.
   */
  shard?: readonly [number, number]
  /** Called after each cell so a long run can report progress. */
  onProgress?: (done: number, total: number, label: string) => void
}

export interface ArmResult {
  arm: BenchmarkArm
  calibration: Calibration
  endpoints: Endpoints
  /** Cells the arm could not run on, with the reason the detector gave. */
  unavailable: Array<{ cell: string; reason: string }>
  /** Milliseconds spent running this arm, for the runtime table the paper needs. */
  runtimeMs: number
  /**
   * Alerts the detector's **own** threshold raised on the null replicates, per site-year.
   *
   * Everything else in this report is measured after the harness has replaced each detector's
   * threshold with a matched empirical one, which is what makes sensitivity comparable and what
   * makes a detector's own alerting invisible. This column is the exception, and it is the only
   * place the benchmark measures what a deployment would actually experience: a control arm
   * whose nominal recurrence interval of 365 days turns out to alert far more or far less than
   * once per site-year is a finding, and it is PACE's third component's reason for existing.
   */
  nativeAlertsPerSiteYear: number
  /** Null signals whose status was `alert` under the detector's own rule. */
  nativeAlerts: number
  /**
   * One row per seeded cell this arm evaluated.
   *
   * The grid-wide `endpoints` above are these rows aggregated. They travel separately because
   * the pre-registered hypothesis is stated on a subgroup of the grid and because a sharded run
   * is pooled from them.
   */
  cells: CellRow[]
}

export interface BenchmarkReport {
  generatedAt: string
  targetRate: number
  windowDays: number
  sites: number
  nullCells: number
  seededCells: number
  seededOutbreaks: number
  nullSiteYears: number
  delayStrideDays: number
  /** `[index, count]` when this process ran one shard of the seeded cells, else null. */
  shard: [number, number] | null
  /** Seeded cells in the whole design, which a shard evaluates only part of. */
  seededCellsInDesign: number
  arms: ArmResult[]
  notes: string[]
}

interface Corpus {
  cell: FactorialCell
  records: IsolateRecord[]
  outbreaks: SeededOutbreak[]
  studyEnd: string
}

/**
 * How many sites the grid needs, counting from the head of `DEMO_SITES`.
 *
 * Null and seeded cells are always generated over the **same** site set. That is not tidiness:
 * the false-alert rate is per site-year, so calibrating on one site and evaluating on four
 * would set a threshold against a quarter of the geography it is then applied to.
 */
export function sitesRequiredFor(design: readonly FactorialCell[]): number {
  const referenced = new Set(design.flatMap((cell) => cell.outbreaks.map((spec) => spec.siteCode)))
  let needed = 1
  for (const [index, site] of DEMO_SITES.entries()) {
    if (referenced.has(site.code)) needed = Math.max(needed, index + 1)
  }
  const unknown = [...referenced].filter((code) => !DEMO_SITES.some((site) => site.code === code))
  if (unknown.length > 0) {
    throw new Error(`The grid seeds outbreaks at ${unknown.join(', ')}, which are not demonstration sites.`)
  }
  return needed
}

function generate(cell: FactorialCell, windowDays: number, sites: number): Corpus {
  const result = simulate({
    seed: cell.seed,
    windowDays,
    backgroundRate: cell.backgroundRate,
    endDate: '2026-08-14',
    sites: DEMO_SITES.slice(0, Math.max(1, sites)),
    outbreaks: cell.outbreaks
  })
  return {
    cell,
    records: result.records,
    outbreaks: result.truth.outbreaks,
    studyEnd: result.truth.study_end
  }
}

function runArm(arm: BenchmarkArm, records: readonly IsolateRecord[]):
{ signals: DetectorSignal[]; reason: string | null } {
  const detector = getDetector(arm.detectorId)
  const context: DetectorContext = {
    records,
    settings: arm.settings,
    seed: 20260814,
    // Only PACE reads these, and reading the 4 MB catalogue asset for a detector that ignores
    // it would cost every cell of a 960-cell grid a parse it does not need.
    ...(arm.detectorId === PACE_ID ? { antibioticClasses: antibioticClasses() } : {})
  }
  const reason = detector.unavailableReason(context)
  if (reason) return { signals: [], reason }
  return { signals: detector.run(context).signals, reason: null }
}

/**
 * The first data cut at which an arm alerts on a seeded outbreak.
 *
 * Truncates the corpus at successive cut dates from the outbreak's first specimen forward and
 * runs the detector at each, which is what makes this a measurement of latency rather than of
 * the corpus's shape. Returns days from the first specimen, or `null` when no cut alerted.
 */
export function detectionDelay(
  arm: BenchmarkArm, corpus: Corpus, outbreak: SeededOutbreak,
  calibration: Calibration, strideDays: number, maxCuts: number
): number | null {
  if (strideDays <= 0 || !outbreak.first_specimen_date) return null
  const start = day(outbreak.first_specimen_date)
  const end = day(corpus.studyEnd)
  const byDay = new Map<number, IsolateRecord[]>()
  for (const record of corpus.records) {
    const recordDay = day(String(record.specimen_date))
    if (!Number.isFinite(recordDay)) continue
    const bucket = byDay.get(recordDay) ?? []
    bucket.push(record)
    byDay.set(recordDay, bucket)
  }
  const sortedDays = [...byDay.keys()].sort((left, right) => left - right)

  let cuts = 0
  for (let cut = start; cut <= end && cuts < maxCuts; cut += strideDays) {
    cuts += 1
    const truncated: IsolateRecord[] = []
    for (const recordDay of sortedDays) {
      if (recordDay > cut) break
      truncated.push(...(byDay.get(recordDay) as IsolateRecord[]))
    }
    if (truncated.length === 0) continue
    const { signals } = runArm(arm, truncated)
    const admitted = alerted(signals, calibration)
    // The outbreak as it stands at this cut: a detector cannot be credited with finding
    // specimens that have not arrived yet.
    const visible: SeededOutbreak = {
      ...outbreak,
      last_specimen_date: outbreak.last_specimen_date
        ? dayKey(Math.min(day(outbreak.last_specimen_date), cut))
        : null
    }
    if (outcomeOf(admitted, [visible]).detected.length > 0) return cut - start
  }
  return null
}

export async function runBenchmark(options: BenchmarkOptions = {}): Promise<BenchmarkReport> {
  const arms = options.arms ?? armsFor()
  const windowDays = options.windowDays ?? 365
  const targetRate = options.targetRate ?? 1
  const delayStrideDays = options.delayStrideDays ?? 0
  const maxDelayCuts = options.maxDelayCuts ?? 12

  const design = factorialDesign({
    ...(options.excessCases ? { excessCases: options.excessCases } : {}),
    ...(options.durationDays ? { durationDays: options.durationDays } : {}),
    ...(options.backgroundRates ? { backgroundRates: options.backgroundRates } : {}),
    ...(options.types ? { types: options.types } : {}),
    ...(options.replicates ? { replicates: options.replicates } : {}),
    ...(options.nullReplicates === undefined ? {} : { nullReplicates: options.nullReplicates }),
    ...(options.baseSeed ? { baseSeed: options.baseSeed } : {})
  })
  const required = sitesRequiredFor(design)
  const sites = options.sites ?? required
  if (sites < required) {
    throw new Error(`This grid seeds outbreaks across ${required} sites and ${sites} were requested. `
      + 'Raise --sites or narrow --types; running with too few would silently drop the cells whose '
      + 'site is missing.')
  }
  const nullCells = design.filter((cell) => cell.outbreaks.length === 0)
  const seededInDesign = design.filter((cell) => cell.outbreaks.length > 0)
  const shard = options.shard ?? null
  if (shard && (shard[1] < 1 || shard[0] < 0 || shard[0] >= shard[1])) {
    throw new Error(`Shard ${shard[0]}/${shard[1]} is not a slice of anything. `
      + 'Use --shard i/n with 0 <= i < n.')
  }
  // Strided rather than blocked, so a shard holds every outbreak type, size and background
  // rather than a contiguous run of one of them. A shard that died would then be missing a
  // slice of the whole grid instead of one entire outbreak type.
  const seededCells = shard
    ? seededInDesign.filter((_, index) => index % shard[1] === shard[0])
    : seededInDesign
  const total = nullCells.length + seededCells.length
  let done = 0

  // ---- 1. nulls, and calibration on them alone ---------------------------------
  const nullSignals = new Map<string, DetectorSignal[]>()
  const unavailable = new Map<string, Array<{ cell: string; reason: string }>>()
  const runtime = new Map<string, number>()
  for (const arm of arms) {
    nullSignals.set(arm.id, [])
    unavailable.set(arm.id, [])
    runtime.set(arm.id, 0)
  }

  for (const cell of nullCells) {
    const corpus = generate(cell, windowDays, sites)
    for (const arm of arms) {
      const started = Date.now()
      const { signals, reason } = runArm(arm, corpus.records)
      runtime.set(arm.id, (runtime.get(arm.id) as number) + (Date.now() - started))
      if (reason) unavailable.get(arm.id)?.push({ cell: cell.arm_id, reason })
      else nullSignals.get(arm.id)?.push(...signals)
    }
    done += 1
    options.onProgress?.(done, total, cell.arm_id)
  }

  const nullSiteYears = siteYearsOf(nullCells.map(() => ({ sites, windowDays })))
  const calibrations = new Map<string, Calibration>()
  for (const arm of arms) {
    calibrations.set(arm.id, calibrate({
      nullSignals: nullSignals.get(arm.id) ?? [],
      siteYears: nullSiteYears,
      targetRate,
      nullCells: nullCells.length
    }))
  }

  // ---- 2. seeded cells, at the calibrated thresholds ----------------------------
  const rows = new Map<string, CellRow[]>()
  for (const arm of arms) rows.set(arm.id, [])

  let seededOutbreaks = 0
  for (const cell of seededCells) {
    const corpus = generate(cell, windowDays, sites)
    // An outbreak the generator could not seed is not a detector's failure to find one.
    const present = corpus.outbreaks.filter((outbreak) => outbreak.observed_cases > 0)
    seededOutbreaks += present.length
    for (const arm of arms) {
      const started = Date.now()
      const { signals, reason } = runArm(arm, corpus.records)
      runtime.set(arm.id, (runtime.get(arm.id) as number) + (Date.now() - started))
      if (reason) {
        unavailable.get(arm.id)?.push({ cell: cell.arm_id, reason })
        continue
      }
      const calibration = calibrations.get(arm.id) as Calibration
      const admitted = alerted(signals, calibration)
      const outcome = outcomeOf(admitted, present)
      const cellDelays: number[] = []
      if (delayStrideDays > 0) {
        for (const outbreak of outcome.detected) {
          const delay = detectionDelay(arm, corpus, outbreak, calibration, delayStrideDays, maxDelayCuts)
          if (delay !== null) cellDelays.push(delay)
        }
      }
      rows.get(arm.id)?.push(rowOf(cell, outcome, cellDelays))
    }
    done += 1
    options.onProgress?.(done, total, cell.arm_id)
  }

  const notes: string[] = [
    'Every arm is calibrated on the null replicates alone and only then run against the seeded '
    + 'cells, so no threshold is chosen with knowledge of the outbreaks it will be asked to find.',
    `Arms are ranked by their own evidence statistic and not by p-value or recurrence interval; `
    + `the scan family uses the log-likelihood ratio, which is why ${BENCHMARK_SETTINGS.permutations} `
    + 'Monte Carlo replications are enough here and would not be in production.'
  ]
  // An arm that was unavailable on every cell is not a weak detector, it is an absent one, and
  // the endpoints table already says "not run" per row. The note repeats it at the top because a
  // reader skimming a seven-arm table can miss one row, and because the reason is usually a
  // property of the corpus rather than of the method: Farrington needs 264 weekly periods before
  // it can test one, which is roughly 1,850 days, and the grid's default window is 365. Running
  // that arm means lengthening the window for *every* arm — the calibration is per site-year over
  // a shared corpus, so an arm on its own longer corpus would not be comparable to the rest.
  for (const arm of arms) {
    const skipped = unavailable.get(arm.id) ?? []
    if (skipped.length > 0 && skipped.length === total) {
      notes.push(`${arm.label} did not run on any of the ${total} cells: ${skipped[0]?.reason ?? ''}`)
    }
  }
  if (delayStrideDays > 0) {
    notes.push(`Detection delay is measured by re-running each arm at data cuts ${delayStrideDays} `
      + `day(s) apart, up to ${maxDelayCuts} cuts. The stride quantises the delay upward and does so `
      + 'identically for every arm, so comparisons hold and absolute figures carry the stride.')
  } else {
    notes.push('Detection delay was not measured in this run: it requires re-running every arm at '
      + 'successive data cuts, and a single run at the data cut would report the outbreak\'s age '
      + 'rather than any property of the detector.')
  }

  return {
    generatedAt: new Date().toISOString(),
    targetRate,
    windowDays,
    sites,
    nullCells: nullCells.length,
    seededCells: seededCells.length,
    seededOutbreaks,
    nullSiteYears,
    delayStrideDays,
    shard: shard ? [shard[0], shard[1]] : null,
    seededCellsInDesign: seededInDesign.length,
    notes,
    arms: arms.map((arm): ArmResult => {
      const calibration = calibrations.get(arm.id) as Calibration
      const nativeAlerts = (nullSignals.get(arm.id) ?? []).filter((signal) => signal.status === 'alert').length
      const armRows = rows.get(arm.id) ?? []
      return {
        arm,
        calibration,
        nativeAlerts,
        nativeAlertsPerSiteYear: nullSiteYears > 0 ? nativeAlerts / nullSiteYears : 0,
        endpoints: endpointsFromRows(armRows, calibration.achievedRate),
        cells: armRows,
        unavailable: unavailable.get(arm.id) ?? [],
        runtimeMs: runtime.get(arm.id) ?? 0
      }
    })
  }
}

export { evidenceOf, rankableDetectors }
